"use client";
import { ArtemisScope } from "./artemis-scope";
import type { ArtemisTestimonialsContent } from "./components/testimonials/content";
import View4 from "./components/testimonials/variants/05-vertical";
const variants={"vertical":View4};
export type { ArtemisTestimonialsContent, ArtemisTestimonialsImage, ArtemisTestimonialsQuote } from "./components/testimonials/content";
export interface ArtemisTestimonialsProps { className?: string; variant?: "vertical"; /** The words on the testimonials; anything left out keeps the layout's own copy. */ content?: Partial<ArtemisTestimonialsContent>; }
export function ArtemisTestimonials({className,variant="vertical",content}:ArtemisTestimonialsProps) {const View=variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View content={content}/></div></ArtemisScope>;}

// @zeus-internal

/** A picture, and the words that describe it. */
export interface ArtemisTestimonialsImage {
  src: string;
  /** What the picture shows; empty for a purely decorative one. */
  alt: string;
}

/** One testimonial: what was said, and who said it. */
export interface ArtemisTestimonialsQuote {
  /** What they said, without quotation marks; marquee, spotlight, grid and vertical add their own. All layouts. */
  quote: string;
  /** Who said it. All layouts. */
  name: string;
  /** Their title and company as one line, such as "Frontend Lead, Workspace". All layouts. */
  role: string;
  /** Their photo. marquee, spotlight, grid and archive, which show the person's initials in its place when you leave it out. */
  avatar?: ArtemisTestimonialsImage;
  /** A short result over the quote, such as "18 days saved". vertical. */
  metric?: string;
}

/** The words on an Artemis testimonials section. Every layout reads this shape, so you can switch layouts and keep them. */
export interface ArtemisTestimonialsContent {
  /** The short label over the heading; over the quote in spotlight. All layouts. */
  badge: string;
  /** The heading. marquee, grid, archive and vertical. */
  headline?: string;
  /** The heading's second part. marquee and grid reveal it after `headline`, archive starts a new line for it, and vertical runs it on after `headline`. Left out, it keeps the layout's own only when `headline` is left out too. */
  headlineAccent?: string;
  /** A sentence beside or under the heading. marquee, grid and archive. */
  subhead?: string;
  /**
   * The testimonials. All layouts. marquee scrolls them in two rows, the first half on top, and eight or more look
   * best; spotlight shows one at a time with a photo button for each, and four look best; grid shows the first one
   * larger; archive pins them in up to three columns; vertical fills three scrolling columns in order, shows the third
   * from 1024px wide, and nine look best.
   */
  quotes: ArtemisTestimonialsQuote[];
  /** The word after the number of quotes, as in "9 dispatches". vertical. */
  countLabel?: string;
  /** A short line beside that count. vertical. */
  note?: string;
}

"use client";
// @zeus-internal
import { useLayoutEffect, useRef, useState } from "react";
import { motion, useReducedMotion } from "motion/react";
import { ARTEMIS_EASE_OUT } from "../../../lib/ease";
import type { ArtemisTestimonialsContent, ArtemisTestimonialsQuote } from "../content";
const DEFAULT = {
    badge: "Field notes",
    headline: "What shipped after the handoff.",
    countLabel: "dispatches",
    note: "Continuous signal",
    quotes: [
        { metric: "18 days saved", quote: "We replaced three weeks of UI work with one afternoon of composition.", name: "Riley Wells", role: "Design engineer, Workspace" },
        { quote: "Our landing page finally has rhythm. The source is clean enough that the team keeps extending it.", name: "Quinn Stone", role: "Frontend lead, Index" },
        { metric: "4 launches shipped", quote: "The variants actually have different taste. That matters more than another hundred components.", name: "Jamie Park", role: "Creative director, Studio Arc" },
        { quote: "The motion feels authored, not sprinkled on after the layout was done.", name: "Taylor Reed", role: "Founder, Group A" },
        { metric: "42 min to production", quote: "The registry workflow is absurdly fast. Install, tune the copy, ship.", name: "Sam Avery", role: "Independent developer" },
        { quote: "Reduced-motion and mobile behavior were already considered. We did not inherit polish debt.", name: "Alex Stone", role: "Accessibility lead, Common" },
        { metric: "+31% conversion", quote: "Every block survived our theme without becoming another generic SaaS section.", name: "Jamie Wells", role: "Product designer, Canopy" },
        { quote: "It gave us the kind of interaction detail we normally cut before launch.", name: "Taylor Parker", role: "VP Product, Group L" },
        { metric: "0 design regressions", quote: "The source feels like it came from a product team, not a component generator.", name: "Casey Reed", role: "Staff engineer, Group M" },
    ],
} satisfies ArtemisTestimonialsContent;
/** One card. Each column lists its cards twice, so the loop has no seam, and tints every second card. */
const card = (item: ArtemisTestimonialsQuote, index: number) => (<article key={index} className={index % 2 === 1 ? "art:relative art:border art:border-border/60 art:p-5 art:bg-[#d84c2f]/[0.06]" : "art:relative art:border art:border-border/60 art:bg-background art:p-5"}>
                      {item.metric ? (<p className="art:mb-8 art:font-mono art:text-xs art:text-[#d84c2f] art:uppercase art:tracking-[0.14em]">
                          {item.metric}
                        </p>) : null}
                      <blockquote className="art:text-pretty art:font-sans art:text-lg art:text-foreground art:leading-7">
                        {"“"}
                        {item.quote}
                        {"”"}
                      </blockquote>
                      <footer className="art:mt-7 art:border-border/60 art:border-t art:pt-4">
                        <p className="art:font-medium art:text-foreground art:text-sm">
                          {item.name}
                        </p>
                        <p className="art:mt-1 art:font-mono art:text-xs art:text-muted-foreground art:uppercase art:tracking-[0.08em]">
                          {item.role}
                        </p>
                      </footer>
                    </article>);
export default function TestimonialsVertical({ content }: { content?: Partial<ArtemisTestimonialsContent> } = {}) {
    const copy = { ...DEFAULT, ...content };
    const count = copy.quotes.length;
    /** The quotes for one of the three columns, filled in order: nine split three, three and three. */
    const column = (index: number) => copy.quotes.slice(Math.ceil(index * count / 3), Math.ceil((index + 1) * count / 3));
    const left = column(0);
    const center = column(1);
    const right = column(2);
    const reduce = useReducedMotion();
    const rootRef = useRef<HTMLDivElement>(null);
    const [embedded, setEmbedded] = useState(false);
    useLayoutEffect(() => setEmbedded(!!rootRef.current?.closest("[data-variant-index]")), []);
    const stopColumns = embedded && reduce;
    return (<>
      <div ref={rootRef} className="art:w-full">
        <section className="art:w-full art:overflow-hidden">
          <style>
            {"\n        @keyframes artemis-ea15206-dispatch-up { from { transform: translateY(0); } to { transform: translateY(-50%); } }\n        @keyframes artemis-ea15206-dispatch-down { from { transform: translateY(-50%); } to { transform: translateY(0); } }\n      "}
          </style>
          <div className="art:mx-auto art:grid art:w-full art:max-w-6xl art:gap-10 art:border-border/60 art:border-y art:py-5 art:@min-[1024px]/artemis:grid-cols-[0.72fr_1.28fr] art:@min-[1024px]/artemis:gap-0 art:@min-[1024px]/artemis:py-0">
            <motion.header key={stopColumns ? "still" : "motion"} className="art:flex art:flex-col art:justify-between art:border-border/60 art:@min-[1024px]/artemis:border-r art:@min-[1024px]/artemis:py-10 art:@min-[1024px]/artemis:pr-10" initial={stopColumns ? false : { opacity: 0, x: reduce ? 0 : -24 }} whileInView={{ opacity: 1, x: 0 }} viewport={{ once: true, margin: "-60px" }} transition={{ duration: 0.65, ease: ARTEMIS_EASE_OUT }}>
              <div>
                <p className="art:font-mono art:text-xs art:text-[#d84c2f] art:uppercase art:tracking-[0.18em]">
                  {copy.badge}
                </p>
                <h2 className="art:mt-5 art:max-w-sm art:text-balance art:font-sans art:text-foreground art:leading-tight art:tracking-[-0.03em] art:text-4xl art:font-medium">
                  {copy.headlineAccent ? `${copy.headline} ${copy.headlineAccent}` : copy.headline}
                </h2>
              </div>
              <div className="art:mt-14 art:grid art:grid-cols-2 art:gap-6 art:border-border/60 art:border-t art:pt-5 art:font-mono art:text-xs art:text-muted-foreground art:uppercase art:tracking-[0.12em]">
                <span>
                  {count}
                  {` ${copy.countLabel}`}
                </span>
                <span>
                  {copy.note}
                </span>
              </div>
            </motion.header>
            <div className="art:group/marquee art:grid art:h-[38rem] art:grid-cols-2 art:gap-3 art:overflow-hidden art:[mask-image:linear-gradient(to_bottom,transparent,black_10%,black_90%,transparent)] art:@min-[1024px]/artemis:grid-cols-3 art:@min-[1024px]/artemis:pl-5">
              <section aria-label="left testimonial column" className="art:overflow-hidden">
                <div style={{ animationName: stopColumns ? "none" : "artemis-ea15206-dispatch-up", animationDuration: "31s", animationTimingFunction: "linear", animationIterationCount: "infinite" }} className="art:will-change-transform art:[animation-play-state:running] art:group-hover/marquee:[animation-play-state:paused]">
                  <div aria-hidden="false" className="art:flex art:flex-col art:gap-3 art:pb-3">
                    {left.map(card)}
                  </div>
                  <div aria-hidden="true" className="art:flex art:flex-col art:gap-3 art:pb-3">
                    {left.map(card)}
                  </div>
                </div>
              </section>
              <section aria-label="center testimonial column" className="art:overflow-hidden">
                <div style={{ animationName: stopColumns ? "none" : "artemis-ea15206-dispatch-down", animationDuration: "35s", animationTimingFunction: "linear", animationIterationCount: "infinite" }} className="art:will-change-transform art:[animation-play-state:running] art:group-hover/marquee:[animation-play-state:paused]">
                  <div aria-hidden="false" className="art:flex art:flex-col art:gap-3 art:pb-3">
                    {center.map(card)}
                  </div>
                  <div aria-hidden="true" className="art:flex art:flex-col art:gap-3 art:pb-3">
                    {center.map(card)}
                  </div>
                </div>
              </section>
              <section aria-label="right testimonial column" className="art:overflow-hidden art:hidden art:@min-[1024px]/artemis:block">
                <div style={{ animationName: stopColumns ? "none" : "artemis-ea15206-dispatch-up", animationDuration: "39s", animationTimingFunction: "linear", animationIterationCount: "infinite" }} className="art:will-change-transform art:[animation-play-state:running] art:group-hover/marquee:[animation-play-state:paused]">
                  <div aria-hidden="false" className="art:flex art:flex-col art:gap-3 art:pb-3">
                    {right.map(card)}
                  </div>
                  <div aria-hidden="true" className="art:flex art:flex-col art:gap-3 art:pb-3">
                    {right.map(card)}
                  </div>
                </div>
              </section>
            </div>
          </div>
        </section>
      </div>
    </>);
}
